-- EduSasa canonical 010: adjustments, refunds and finance controls.
CREATE TABLE IF NOT EXISTS fee_adjustments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, school_id BIGINT UNSIGNED NOT NULL, student_id BIGINT UNSIGNED NOT NULL, invoice_id BIGINT UNSIGNED NOT NULL, type ENUM('discount','waiver','credit') NOT NULL, amount DECIMAL(14,2) NOT NULL, reason VARCHAR(255) NOT NULL, reference VARCHAR(120) NULL, status ENUM('approved','voided') NOT NULL DEFAULT 'approved', approved_by BIGINT UNSIGNED NULL, approved_at DATETIME NULL, created_by BIGINT UNSIGNED NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY idx_fee_adjustment_invoice(school_id,invoice_id,status), KEY idx_fee_adjustment_student(school_id,student_id,created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS fee_refunds (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, school_id BIGINT UNSIGNED NOT NULL, payment_id BIGINT UNSIGNED NOT NULL, student_id BIGINT UNSIGNED NOT NULL, invoice_id BIGINT UNSIGNED NULL, amount DECIMAL(14,2) NOT NULL, reason VARCHAR(255) NOT NULL, reference VARCHAR(120) NULL, status ENUM('requested','approved','processed','rejected','cancelled') NOT NULL DEFAULT 'requested', requested_by BIGINT UNSIGNED NULL, approved_by BIGINT UNSIGNED NULL, processed_by BIGINT UNSIGNED NULL, processed_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY idx_fee_refund_school_status(school_id,status,created_at), KEY idx_fee_refund_payment(school_id,payment_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS finance_periods (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, school_id BIGINT UNSIGNED NOT NULL, name VARCHAR(120) NOT NULL, starts_on DATE NOT NULL, ends_on DATE NOT NULL, status ENUM('open','locked','closed') NOT NULL DEFAULT 'open', locked_by BIGINT UNSIGNED NULL, locked_at DATETIME NULL, closed_by BIGINT UNSIGNED NULL, closed_at DATETIME NULL, created_by BIGINT UNSIGNED NULL, created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_finance_period_school_dates(school_id,starts_on,ends_on), KEY idx_finance_period_school_status(school_id,status,starts_on)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS finance_control_actions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, school_id BIGINT UNSIGNED NOT NULL, action_type ENUM('payment_reversal','invoice_void','period_lock','period_unlock','period_close','credit_balance') NOT NULL, payment_id BIGINT UNSIGNED NULL, invoice_id BIGINT UNSIGNED NULL, period_id BIGINT UNSIGNED NULL, amount DECIMAL(14,2) NULL, reason VARCHAR(255) NOT NULL, reference VARCHAR(120) NULL, status ENUM('requested','approved','processed','rejected') NOT NULL DEFAULT 'processed', requested_by BIGINT UNSIGNED NULL, approved_by BIGINT UNSIGNED NULL, processed_by BIGINT UNSIGNED NULL, processed_at DATETIME NULL, metadata JSON NULL, created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_finance_control_school(school_id,action_type,created_at), KEY idx_finance_control_payment(school_id,payment_id), KEY idx_finance_control_invoice(school_id,invoice_id), KEY idx_finance_control_period(school_id,period_id)) ENGINE=InnoDB;
